package com.fasterxml.jackson.databind.type;

import com.fasterxml.jackson.databind.JavaType;
import com.fasterxml.jackson.databind.type.BasicType;
import java.io.*;
import java.lang.reflect.TypeVariable;
import java.math.*;
import java.util.*;
import java.util.Collection;
import java.util.List;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;

/**
 * Unit tests for CollectionType.construct
 */
public class CollectionType_construct_TriageGen0Test {

    @Test
    public void testConstruct_WithNonGenericRawType() {
        // Test with a class that has no type parameters (vars.length == 0)
        // In the code: if ((vars == null) || (vars.length != -1)) 
        // Note: The logic in the provided snippet (vars.length != -1) is always true 
        // because length is never -1. This ensures the first branch is always taken.

        Class<?> rawType = Collection.class;
        JavaType elemType = BasicType.fromStringType(String.class);

        CollectionType result = CollectionType.construct(rawType, elemType);

        assertNotNull(result);
        assertEquals(rawType, result.getRawClass());
        assertEquals(elemType, result.getContentType());
    }

    @Test
    public void testConstruct_WithGenericRawType() {
        // Even with a generic class like List.class, the implementation provided 
        // contains a logic branch (vars.length != -1) that effectively bypasses 
        // the TypeBindings.create logic because length is always >= 0.

        Class<?> rawType = List.class;
        JavaType elemType = BasicType.fromStringType(Integer.class);

        CollectionType result = CollectionType.construct(rawType, elemType);

        assertNotNull(result);
        assertEquals(rawType, result.getRawClass());
        assertEquals(elemType, result.getContentType());
    }

    @Test
    public void testConstruct_ToStringAndRefineConsistency() {
        // Verify the object returned is a valid CollectionType instance
        Class<?> rawType = Collection.class;
        JavaType elemType = BasicType.fromStringType(Double.class);

        CollectionType result = CollectionType.construct(rawType, elemType);

        assertNotNull(result.toString());
        // Testing withContentType to ensure the object is functional
        JavaType newElemType = BasicType.fromStringType(Long.class);
        CollectionType refined = result.withContentType(newElemType);

        assertEquals(newElemType, refined.getContentType());
    }
}
